import { curriculum } from './curriculum.mjs';
import { escapeText as e } from './lesson_pages.mjs';

// Original teaching material. Stage labels describe prerequisites, not official certification.
export const points = [
 {id:'past-perfect',stage:'國中',title:'過去式與現在完成式：時間如何選？',goal:'看懂「已結束的過去」與「連到現在的經驗或狀態」。',prior:'先會動詞過去式、過去分詞與 have / has。',rule:'過去式把事件放在已結束的過去時間；現在完成式用 have / has + 過去分詞，連結過去與現在。不是看到中文「已經」就選完成式。',pairs:[['I lost my key yesterday.','昨天弄丟：時間已結束，用 lost。'],['I have lost my key.','現在還受到影響，例如目前沒鑰匙可用。'],['She has lived here for three years.','住了三年，通常表示目前仍住這裡。']],steps:['先找時間：yesterday、last year、in 2020 指明結束的過去。','再問是否持續到現在：since + 起點；for + 時間長度。for 也能搭配過去式，不能單靠它判斷。','比較 He lived here for three years（那段居住已結束）與 He has lived here for three years（延續至今）。'],trap:'錯：I have seen her yesterday. → I saw her yesterday. 完成式與明確結束的 yesterday 不相配。',questions:[['We ___ the museum last Sunday.',['visited','have visited','have visit'],0,'last Sunday 是結束的過去；visited 是過去式。have visited 不搭這個時間，have visit 缺過去分詞。'],['Mia still works here. She ___ here since 2022.',['worked','has worked','is work'],1,'still 和 since 指向延續至今，選 has worked。單純 worked 無法表達此處的持續關係；is work 結構錯誤。']],task:'各寫一句：昨天完成的事，以及持續到現在的習慣或狀態。加入時間線索。',model:'I finished my report yesterday. I have known Amy for five years. 檢查：第一句有已結束時間；第二句用 have + known，for 後接時間長度。'},
 {id:'relative-clauses',stage:'高中',title:'關係子句：先找缺口，再選代名詞',goal:'分辨關係代名詞在子句中當主詞或受詞，避免重複代名詞。',prior:'能找出一句話的主詞、動詞與受詞。',rule:'關係子句修飾名詞。先把子句還原成獨立句，再找缺少的成分。who 常指人、which 指事物；限定用法中的 that 可指人或事物。',pairs:[['The girl who won the race is my sister.','who 是 won 的主詞，不可省略。'],['The book (that) I bought is useful.','I bought the book：缺受詞，限定子句的關係代名詞可以省略。'],['My bike, which is red, is outside.','逗號後補充資訊的非限定子句用 which，不用 that，也不可省略。']],steps:['圈出被修飾的名詞：girl、book、bike。','檢查子句：___ won the race 缺主詞；I bought ___ 缺受詞。','最後檢查逗號：非限定子句的代名詞不能省略；地點詞也不必然選 where，仍要看缺口。'],trap:'錯：The book that I bought it is useful. → 刪除 it；that 已代表 bought 的受詞。The city which I visited 用 which，因 visited 缺受詞。',questions:[['The student ___ helped me is Leo.',['who','whom','where'],0,'缺 helped 的主詞，用 who。whom 是受詞形式；where 表地點關係，不能當此處主詞。'],['Which sentence is correct?',['The movie that I watched it was moving.','The movie I watched was moving.','The movie, that I watched, was moving.'],1,'限定子句中 watched 的受詞代名詞可省略。第一句 it 重複；第三句非限定用法不能使用 that。']],task:'用同一個名詞寫兩句，一句讓關係代名詞當主詞，一句當受詞。',model:'The teacher who teaches English is kind. The teacher I met yesterday is kind. 第二句可加入 whom / who / that；第一句不能省略 who。'},
 {id:'passive-instructions',stage:'高工',title:'被動語態：讀懂操作步驟與安全要求',goal:'在操作文件中辨認動作、執行者與必要條件。',prior:'理解及物動詞、過去分詞與 must / should。',rule:'被動語態用 be + 過去分詞，讓接受動作的事物成為主詞。時態由 be 表示；情態動詞後用原形 be。操作文件常省略執行者，但不能因此忽略動作的條件。',pairs:[['The technician checks the valve.','主動：重點是技術員做什麼。'],['The valve is checked every morning.','被動：重點是閥門的例行檢查。'],['The power must be disconnected before cleaning.','must be + disconnected：清潔前必須切斷電源。這是語言示例；實際操作須依設備手冊。']],steps:['找接受動作的物件：valve、power。','判斷時間或要求：is checked 表例行，was checked 表過去，must be checked 表必要要求。','保留 before / after / until 等順序和條件；翻譯時不能把 must 改成「可以」。'],trap:'錯：The machine must turned off. → must be turned off。錯：The accident was happened. → The accident happened；happen 不帶受詞，不用此被動結構。',questions:[['The filter must ___ before use.',['replace','be replaced','replaced'],1,'must 後接原形 be，再接 replaced。replace 是主動式，單獨 replaced 缺 be。'],['The parts were inspected yesterday. What does this mean?',['The inspection is a future plan.','Someone inspected the parts yesterday.','The parts inspected the worker.'],1,'were inspected 是過去被動，等同有人昨天檢查零件。不是未來計畫，也不是零件執行檢查。']],task:'將 Workers must label the containers before shipment. 改成被動，保留義務與時間條件。',model:'The containers must be labeled before shipment. 檢查：複數主詞 containers、must be + labeled、before shipment 全部保留；labelled 也是正確拼法。'},
 {id:'countability',stage:'國中',title:'可數與不可數：量詞不是逐字翻譯',goal:'正確使用 a / an、many / much，以及資訊與建議的量詞。',prior:'理解單數與複數名詞。',rule:'可數名詞可以一個一個計數，單數通常需要限定詞；不可數名詞以整體或材料看待，通常不加 a 或複數 s。必須看語境：paper 是紙，a paper 可以是一篇論文。',pairs:[['I need some advice.','advice 通常不可數，不寫 an advice 或 advices。'],['She gave me two pieces of information.','information 不可數；用 pieces 表示兩則。'],['There are a few chairs, but little space.','chairs 可數；space 在此指空間，不可數。']],steps:['先問此處意思是個體還是整體，不只看中文量詞。','可數複數搭 many / a few；不可數搭 much / a little；some、a lot of 可搭兩者。','few / little 表很少、幾乎沒有；a few / a little 表仍有一些。'],trap:'錯：There are many equipments. → There is a lot of equipment. equipment 通常不可數，連帶影響 is / are。',questions:[['Which phrase is correct?',['an information','three advices','a little water'],2,'water 在此不可數，搭 a little。information 和 advice 不用 a 或直接加 s。'],['We have ___ time, so we cannot finish today.',['little','a few','many'],0,'time 在此不可數；little 配合無法完成的負面語意。a few 和 many 要接可數複數。']],task:'寫一張購物或準備清單：兩種可數物品與兩種不可數物品，各附量詞。',model:'two notebooks, a few pens, some water, a little rice。檢查 notebooks / pens 有複數，water / rice 不直接加 s。'},
 {id:'reading-evidence',stage:'國際考試',title:'閱讀推論：答案必須有文本證據',goal:'區分直接資訊、合理推論與無法證實的猜測。',prior:'能讀懂簡單過去式與 because / although。',rule:'推論是將文本線索接成最小而必要的結論，不能加入自己的背景故事。SAT、GRE、TOEFL 等閱讀練習都需要證據判斷；本頁是原創共通能力教材，不是官方試題。',pairs:[['The library extended its evening hours after students requested more study space.','直接資訊：學生提出需求，圖書館延長晚間開放。'],['The change responded to student demand.','合理推論：改變回應了需求。'],['Every student now gets higher grades.','無法證實：沒有所有學生、成績或因果效果的資料。']],steps:['用自己的話摘要原文，不先看選項。','替候選答案畫出證據，檢查主詞、時間與程度詞：some 不能擴成 all。','淘汰「可能是真的但文中未支持」的說法；相關或先後順序不自動證明因果。'],trap:'「延長開放後成績上升」也不能單靠先後順序證明延長開放造成成績上升；還可能有其他因素。',questions:[['Some participants reported better sleep. Which conclusion is supported?',['All participants slept better.','At least some participants said their sleep improved.','The program certainly cured insomnia.'],1,'some 支持至少一部分人的自陳改善。All 擴大量詞；certainly cured 擴大到確定治療效果。'],['Sales rose after a new ad appeared. What can we conclude from this alone?',['The ad caused the rise.','The rise happened after the ad appeared.','No other factor affected sales.'],1,'原文僅支持時間先後。因果與排除其他因素都需要額外證據。']],task:'針對圖書館短文，寫一項直接資訊、一項合理推論，以及一項目前無法知道的資訊。',model:'直接資訊：延長晚間開放。推論：改變回應學生需求。未知：成績是否提升。檢查每個結論是否超出文中人數、範圍或因果。'},
 {id:'argument-assumptions',stage:'國際考試',title:'論證假設：找出理由與結論之間的缺口',goal:'辨認結論、證據與必要假設，練習反例檢驗。',prior:'先能區分事實敘述與作者主張。',rule:'證據是作者提供的理由，結論是作者要你接受的主張。必要假設是論證成立所依賴、卻未說明的條件。GMAT 與 GRE 相關閱讀練習可運用這個方法；題目問必要假設或加強論證時，判準不同。',pairs:[['A bus service proposes adding trips because current buses are crowded. It predicts the extra trips will reduce crowding.','證據：現有班次擁擠。結論：新增班次能減少擁擠。'],['The extra trips can serve at least some of the passengers who currently crowd the buses.','必要的連結：新增服務要能承接原本擁擠的需求。'],['Every passenger prefers buses to trains.','過強且非必要：即使有人偏好火車，增加適當班次仍可能減少擁擠。']],steps:['標出結論：所以、預測、建議之後常是結論，但仍要依語意判斷。','問「理由都是真的時，結論還可能錯在哪裡？」例如新增班次不在尖峰時段。','對必要假設取否定：若新增班次完全不能承接原擁擠乘客，推論就失去依據。否定檢驗不等於把任何加強選項都當必要。'],trap:'加強選項可能只讓結論更可信，卻不是缺它不可。另勿把「否定某選項」誤作「把結論反過來」。',questions:[['Which most weakens the bus prediction?',['The extra trips run only when the buses are already almost empty.','The buses are blue.','Some riders carry backpacks.'],0,'非擁擠時段增班無法回應原來的問題，直接攻擊證據與結論連結。車色與背包沒有提供相關反證。'],['Which statement is the conclusion?',['Current buses are crowded.','Extra trips will reduce crowding.','A service operates buses.'],1,'作者以現有擁擠為理由，支持「新增班次會減少擁擠」的預測；預測是結論。']],task:'為「公司改用新軟體，所以工作必定更快」寫一個尚未證實的條件，再寫一個可能反例。',model:'條件：員工能有效使用新軟體，而且主要工作瓶頸能被它改善。反例：軟體操作訓練耗時，或真正瓶頸是等待客戶回覆。避免只以「軟體很新」推論必定更快。'}
];
let query='';
export function knowledgeResults(search=query){const term=search.trim().toLowerCase();const cards=points.map(p=>({title:p.title,stage:p.stage,description:p.goal,link:`href="#knowledge/${p.id}"`,search:p.rule})).concat(curriculum.flatMap(t=>t.chapters.map(c=>({title:c.title,stage:t.title,description:c.concepts.map(x=>x.heading).join(' · '),link:`href="#chapter/${t.id}/${c.id}"`,search:c.concepts.map(x=>x.body).join(' ')}))));const found=cards.filter(c=>`${c.title} ${c.stage} ${c.description} ${c.search}`.toLowerCase().includes(term));return `<p role="status">${found.length} 個教學頁面</p><div class="knowledge-grid">${found.map(c=>`<a class="knowledge-card" ${c.link}><span class="pill">${e(c.stage)}</span><h2>${e(c.title)}</h2><p>${e(c.description)}</p><span>開始學習 →</span></a>`).join('')}</div>${!found.length?'<p>找不到相符內容，試試「時態」、「閱讀」或「國中」。</p>':''}`;}
export function knowledgeHome(){return `<section class="knowledge-home"><header><p class="pill">理解 → 看例子 → 自己做 → 複習</p><h1>今天想弄懂哪個知識點？</h1><p>從一個觀念開始。每章包含解說、例句與練習；讀完後，用自己的話再說一次。</p></header><label for="knowledge-search">搜尋主題、程度或英文關鍵字</label><input type="search" id="knowledge-search" value="${e(query)}" placeholder="例如：國中、被動、閱讀、完成式"><p class="small">這是現有教材入口，並不表示已完整涵蓋各課綱或考試。想按學期學習，可開啟「學年課程地圖」。</p><div id="knowledge-results">${knowledgeResults()}</div></section>`;}
export function searchKnowledge(target){if(target.id!=='knowledge-search')return;query=target.value;document.querySelector('#knowledge-results').innerHTML=knowledgeResults();}
export function knowledgePage(id){const p=points.find(x=>x.id===id);if(!p)return '<h1>找不到這個知識點</h1><a href="#knowledge">回知識點教室</a>';return `<article class="lesson-page knowledge-detail"><a href="#knowledge">← 回知識點教室</a><header><p class="pill">${e(p.stage)} · 原創教學</p><h1>${e(p.title)}</h1><p>${e(p.goal)}</p><p class="small">先備知識：${e(p.prior)}</p></header><nav class="lesson-links" aria-label="本頁段落"><button class="btn quiet" data-scroll-to="#kp-concept">觀念</button><button class="btn quiet" data-scroll-to="#kp-examples">例句</button><button class="btn quiet" data-scroll-to="#kp-practice">練習</button><button class="btn quiet" data-scroll-to="#kp-output">應用</button></nav><section class="card" id="kp-concept"><h2>1. 理解核心觀念</h2><p>${e(p.rule)}</p><ol>${p.steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol></section><section class="card" id="kp-examples"><h2>2. 對照例句與錯誤</h2>${p.pairs.map(([en,zh])=>`<blockquote><p lang="en">${e(en)}</p><p>${e(zh)}</p></blockquote>`).join('')}<aside class="lesson-tip">${e(p.trap)}</aside></section><section class="card" id="kp-practice"><h2>3. 先作答，再看解析</h2>${p.questions.map((q,i)=>`<fieldset class="lesson-check"><legend>${i+1}. ${e(q[0])}</legend>${q[1].map((o,j)=>`<button class="btn quiet lesson-option" data-kp-answer="${p.id}:${i}:${j}">${String.fromCharCode(65+j)}. ${e(o)}</button>`).join('')}<p class="kp-feedback" role="status"></p></fieldset>`).join('')}</section><section class="card" id="kp-output"><h2>4. 換個情境使用</h2><label for="kp-draft">${e(p.task)}</label><textarea id="kp-draft" rows="5" placeholder="請先寫下自己的答案，再展開範例。"></textarea><p class="small">本頁草稿僅保留到離開頁面，離開前請複製。</p><details><summary>參考答案與自查</summary><p>${e(p.model)}</p></details><h3>明天再回想</h3><p>不看本文說出規則，重新造一個句子，再檢查是否犯了本頁列出的錯誤。</p></section><a href="#knowledge">選下一個知識點 →</a></article>`;}
export function answerKnowledge(button){if(!button.dataset.kpAnswer)return false;const [id,qi,ai]=button.dataset.kpAnswer.split(':');const q=points.find(p=>p.id===id)?.questions[Number(qi)];if(!q)return true;const field=button.closest('fieldset');field.querySelector('.kp-feedback').textContent=`${Number(ai)===q[2]?'答對':'需要訂正'}。正解：${q[1][q[2]]}。${q[3]}`;field.querySelectorAll('button').forEach(b=>b.disabled=true);return true;}
